#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk #:package Avalonia@11.3.10 #:package Avalonia.Desktop@11.3.10 #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable  using Avalonia; using Avalonia.Controls; using Avalonia.Controls.ApplicationLifetimes; using Avalonia.Layout; using System;  namespace BasicAvaloniaApp {     public class MainWindow : Window     {         private int _counter = 0;         private bool _isDarkTheme = false;                  public MainWindow()         {             Title = "Avalonia Production App";             Width = 400;             Height = 300;                          // 创建UI组件             var grid = new Grid             {                 ColumnDefinitions = new ColumnDefinitions("*, 80"),                 RowDefinitions = new RowDefinitions("Auto, Auto, Auto, Auto"),                 Margin = new Thickness(20)             };                          // 标题             var titleText = new TextBlock             {                 Text = "Hello, Avalonia!",                 FontSize = 24,                 FontWeight = Avalonia.Media.FontWeight.Bold,                 HorizontalAlignment = HorizontalAlignment.Center             };             Grid.SetColumn(titleText, 0);             Grid.SetColumnSpan(titleText, 2);             Grid.SetRow(titleText, 0);             grid.Children.Add(titleText);                          // 计数器文本             var counterText = new TextBlock             {                 Text = $"Counter: {_counter}",                 Margin = new Thickness(0, 10, 0, 0),                 FontSize = 16             };             Grid.SetColumn(counterText, 0);             Grid.SetRow(counterText, 1);             grid.Children.Add(counterText);                          // 递增按钮             var incrementButton = new Button             {                 Content = "Increment",                 Margin = new Thickness(0, 10, 0, 0)             };             Grid.SetColumn(incrementButton, 0);             Grid.SetRow(incrementButton, 2);             incrementButton.Click += (sender, e) =>             {                 _counter++;                 counterText.Text = $"Counter: {_counter}";             };             grid.Children.Add(incrementButton);                          // 主题切换按钮             var themeButton = new Button             {                 Content = "Toggle Theme",                 Margin = new Thickness(10, 10, 0, 0)             };             Grid.SetColumn(themeButton, 1);             Grid.SetRow(themeButton, 2);             themeButton.Click += (sender, e) =>             {                 _isDarkTheme = !_isDarkTheme;                 RequestedThemeVariant = _isDarkTheme ? Avalonia.Styling.ThemeVariant.Dark : Avalonia.Styling.ThemeVariant.Light;             };             grid.Children.Add(themeButton);                          Content = grid;         }     }          public class App : Application     {         public override void OnFrameworkInitializationCompleted()         {             if (ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop)             {                 desktop.MainWindow = new MainWindow();             }                          base.OnFrameworkInitializationCompleted();         }     }          public static class Program     {         public static void Main(string[] args)         {             BuildAvaloniaApp()                 .StartWithClassicDesktopLifetime(args, ShutdownMode.OnLastWindowClose);         }                  public static AppBuilder BuildAvaloniaApp()         {             return AppBuilder.Configure<App>()                 .UsePlatformDetect()                 .LogToTrace();         }     } }
